-- 既存の auth.users に同一メールアドレスが既に存在する場合、IDの不整合を防ぐため一時テーブル側を同期
UPDATE tmp_seed_users t
SET id = u.id
FROM auth.users u
WHERE lower(u.email) = lower(t.email);

-- 1. auth.users に未登録のユーザーのみを安全にINSERT (emailまたはID重複を自動スキップ)
INSERT INTO auth.users (
  instance_id,
  id,
  aud,
  role,
  email,
  encrypted_password,
  email_confirmed_at,
  raw_app_meta_data,
  raw_user_meta_data,
  created_at,
  updated_at
)
SELECT
  '00000000-0000-0000-0000-000000000000',
  t.id,
  'authenticated',
  'authenticated',
  t.email,
  crypt('TestUser2026!', gen_salt('bf')),
  now(),
  '{"provider":"email","providers":["email"]}'::jsonb,
  jsonb_build_object('name', t.name, 'role', t.role),
  now(),
  now()
FROM tmp_seed_users t
WHERE NOT EXISTS (
  SELECT 1 FROM auth.users u WHERE lower(u.email) = lower(t.email) OR u.id = t.id
);

-- 2. public.profiles (auth.users に存在するユーザーを確実に反映・更新)
INSERT INTO public.profiles (
  id,
  role,
  name,
  email,
  phone,
  avatar_url,
  address,
  postal_code,
  lat,
  lng,
  created_at,
  updated_at
)
SELECT
  t.id,
  t.role,
  t.name,
  t.email,
  t.phone,
  t.avatar_url,
  t.address,
  t.postal_code,
  t.lat,
  t.lng,
  now(),
  now()
FROM tmp_seed_users t
JOIN auth.users u ON u.id = t.id
ON CONFLICT (id) DO UPDATE SET
  role = EXCLUDED.role,
  name = EXCLUDED.name,
  email = EXCLUDED.email,
  phone = EXCLUDED.phone,
  avatar_url = EXCLUDED.avatar_url,
  address = EXCLUDED.address,
  postal_code = EXCLUDED.postal_code,
  lat = EXCLUDED.lat,
  lng = EXCLUDED.lng,
  updated_at = now();

