  ('322fbe88-d989-44e7-a30b-027745296b3c', '離乳食インストラクター・保育士。離乳食初期のスプーンの進め方から、後期の偏食・手づかみ食べまで。実際にご自宅の台所で一緒に作りながらアドバイスします。', ARRAY['離乳食調理実演指導', '食べムラ・偏食対策', 'アレルギー配慮レシピ'], false, true, '愛媛県松山市此花町5-11', ST_SetSRID(ST_MakePoint(132.782, 33.839), 4326), 15, 4.96, 44, true, 'acct_ehime_parent03', '{"badge":"レシピ集贈呈","title":"簡単・時短「離乳食アレンジレシピ集」プレゼント","description":"ご相談いただいた方に特製レシピブックを進呈いたします！","valid_until":"2026-11-30","discount_type":"gift","discount_value":0}'::jsonb, now(), now()),
  ('0310b1a2-7dab-4022-ae60-b12719d5fd42', '夜泣き改善専門サポーター・チャイルドマインダー。西条・新居浜エリア出張。赤ちゃんの睡眠リズムを整え、親子がぐっすり眠れる寝室環境と生活スケジュールを提案します。', ARRAY['夜泣き・寝かしつけ改善', '乳幼児睡眠リズム調整', '育児ストレスケア'], false, true, '愛媛県西条市朔日市781-2', ST_SetSRID(ST_MakePoint(133.178, 33.921), 4326), 20, 4.92, 31, true, 'acct_ehime_parent04', NULL, now(), now()),
  ('eb513594-8546-41de-a475-704b816b96a8', '子育て支援専門士・ベビーマッサージ講師。松前町・伊予市対応。親子の触れ合いを通じて赤ちゃんの便秘や夜泣きを緩和し、ママ・パパの育児不安に温かく寄り添います。', ARRAY['ベビーマッサージ', '親子スキンシップ', 'イヤイヤ期・発達相談'], true, true, '愛媛県伊予郡松前町筒井1425-1', ST_SetSRID(ST_MakePoint(132.715, 33.7885), 4326), 15, 4.91, 27, true, 'acct_ehime_parent05', NULL, now(), now()),
  ('e97736bf-a91a-4f01-ae76-61a8647ae61e', 'AEAJ認定アロマセラピスト。松山市中心部のプライベートサロン＆出張施術。体調やお好みに合わせて10種類以上のオーガニック精油をブレンドし、深層リンパを流します。', ARRAY['オーダーメイドアロマリンパ', '冷え・むくみ改善', '自律神経調整トリートメント'], true, true, '愛媛県松山市二番町3丁目7-1', ST_SetSRID(ST_MakePoint(132.7695, 33.8391), 4326), 15, 4.94, 38, true, 'acct_ehime_aroma04', '{"badge":"初回20%OFF","title":"極上アロマリンパ初回限定20%OFF","description":"初めての方限定で極上アロマリンパメニューが20%OFF！","valid_until":"2026-11-30","discount_type":"percent","discount_value":20}'::jsonb, now(), now()),
  ('b55d9acb-6c5e-4665-a87a-680847ca88a8', '南予・宇和島エリア出張対応。玄武岩の温もりで身体の芯から温めるホットストーン＆アロマトリートメント。慢性的な肩こりや冷え性にじんわり効きます。', ARRAY['ホットストーンセラピー', '深層温活アロマ', '疲労回復ボディケア'], false, true, '愛媛県宇和島市錦町4-10', ST_SetSRID(ST_MakePoint(132.561, 33.223), 4326), 30, 4.88, 23, true, 'acct_ehime_aroma05', NULL, now(), now()),
  ('1978a358-7fc6-4689-ada3-707a3d7d1253', '作業療法士歴14年。脳卒中後遺症や骨折後の日常生活動作（着替え・入浴・家事）獲得リハビリをご自宅で支援。福祉用具の選定や住宅改修のアドバイスも対応。', ARRAY['生活行為向上リハビリ', '麻痺側上肢機能訓練', '住宅改修・福祉用具提案'], false, true, '愛媛県松山市御幸1丁目4-15', ST_SetSRID(ST_MakePoint(132.768, 33.856), 4326), 20, 4.93, 36, true, 'acct_ehime_ot04', '{"badge":"初回評価無料","title":"初回訪問生活機能アセスメント無料","description":"日常生活の動作チェックとリハビリ計画立案を初回無料で実施します。","valid_until":"2026-12-31","discount_type":"gift","discount_value":0}'::jsonb, now(), now()),
  ('c69716e4-be40-4872-a9b4-1c5b5ff6f808', '八幡浜・大洲エリア出張対応。認知症予防や手先の巧緻性向上、趣味活動（園芸・手芸等）を取り入れたメンタルケア＆身体リハビリを提供します。', ARRAY['認知症ケア作業療法', '手先巧緻性リハビリ', '精神科作業療法'], false, true, '愛媛県八幡浜市北浜1丁目2-8', ST_SetSRID(ST_MakePoint(132.423, 33.459), 4326), 25, 4.89, 21, true, 'acct_ehime_ot05', NULL, now(), now()),
  ('8d858c28-c492-45cf-a5cc-f29e796eeffd', '言語聴覚士。嚥下（飲み込み）障害の専門アセスメントや安全な食事介助法の指導、むせ込み予防の嚥下体操をご自宅で実践的に指導します。', ARRAY['摂食嚥下リハビリ', '安全なとろみ・形態指導', '構音障害トレーニング'], false, true, '愛媛県松山市萱町3丁目2-1', ST_SetSRID(ST_MakePoint(132.759, 33.8465), 4326), 20, 4.95, 41, true, 'acct_ehime_st04', '{"badge":"嚥下評価進呈","title":"初回嚥下スクリーニングシート無料進呈","description":"初回訪問時に嚥下状態のチェックシートと対策マニュアルを差し上げます。","valid_until":"2026-12-15","discount_type":"gift","discount_value":0}'::jsonb, now(), now()),
  ('7050ce64-ab05-4c11-a921-a0d65ee12acf', '東予エリア（新居浜・西条）対応。脳梗塞後の失語症リハビリや、パーキンソン病等に伴う声の小ささ・発話の不明瞭さを改善する発声トレーニングを行います。', ARRAY['失語症コミュニケーション訓練', '声量アップ発声リハビリ', '認知機能訓練'], false, true, '愛媛県新居浜市西の土居町1丁目3-2', ST_SetSRID(ST_MakePoint(133.275, 33.951), 4326), 25, 4.9, 27, true, 'acct_ehime_st05', NULL, now(), now()),
  ('a7a04fb2-809d-474b-ae20-c146800cfcfb', '日本訪問歯科協会認定歯科衛生士。要介護高齢者や通院が困難な方のご自宅・施設へ伺い、お口の専門的清掃（口腔ケア）と歯肉マッサージを実施。誤嚥性肺炎を予防します。', ARRAY['専門的口腔ケア', '誤嚥性肺炎予防ケア', '口腔乾燥症保湿マッサージ'], false, true, '愛媛県松山市湊町4丁目11-1', ST_SetSRID(ST_MakePoint(132.766, 33.836), 4326), 18, 4.96, 47, true, 'acct_ehime_dh04', '{"badge":"ケア用品贈呈","title":"専用口腔スポンジ＆保湿ジェルセットプレゼント","description":"初回訪問時に日々の口腔ケア用スポンジ＆ジェルを進呈！","valid_until":"2026-11-30","discount_type":"gift","discount_value":0}'::jsonb, now(), now()),
  ('5e8ad113-70e4-496e-a6d8-ae884c486bb5', '今治市エリア。審美歯科・ホワイトニングサロン経験を持つ歯科衛生士。歯の黄ばみ・着色汚れ除去やリップエステ、お口元の筋肉をほぐすオーラルエステを提供。', ARRAY['オーラルデンタルエステ', '着色ステイン除去', '唾液腺マッサージ'], true, true, '愛媛県今治市本町3丁目2-5', ST_SetSRID(ST_MakePoint(133.003, 34.0645), 4326), 20, 4.91, 30, true, 'acct_ehime_dh05', NULL, now(), now()),
  ('1084b8dc-1b8c-4eec-a04d-90e57a3d3e30', 'はり師・きゅう師国家資格保持者。極細のディスポーザブル（使い捨て）鍼を使用した痛みのない美容鍼灸と、慢性肩こり・腰痛の深層筋トリガーポイント鍼灸が得意です。', ARRAY['美容鍼灸・小顔リフト', 'トリガーポイント鍼灸', '自律神経調整灸'], true, true, '愛媛県松山市三番町2丁目6-8', ST_SetSRID(ST_MakePoint(132.7725, 33.8385), 4326), 15, 4.97, 53, true, 'acct_ehime_acu04', '{"badge":"初回2,000円引","title":"美容鍼灸初回体験2,000円引きキャンペーン","description":"初めての美容鍼コースをご予約で2,000円割引！","valid_until":"2026-11-30","discount_type":"fixed","discount_value":2000}'::jsonb, now(), now()),
  ('9298c004-a7aa-4d7b-a466-63a85e790bbf', '大洲・南予エリア出張対応。温かいお灸を中心としたやさしい東洋医学的アプローチ。冷え性、月経痛、更年期の不快な症状を芯から緩和します。', ARRAY['温灸セラピー', '婦人科トラブルケア', '冷え症根本改善'], false, true, '愛媛県大洲市東大洲1520-3', ST_SetSRID(ST_MakePoint(132.559, 33.515), 4326), 25, 4.9, 25, true, 'acct_ehime_acu05', NULL, now(), now()),
  ('acc5712e-e2d5-4ba1-a96d-c4763e188c09', '病院管理栄養士歴10年。高血圧・糖尿病・脂質異常症などの検査数値を改善するための美味しく続けられる減塩・糖質コントロールメニューをご提案。冷蔵庫の食材で作る献立指導も好評。', ARRAY['生活習慣病栄養指導', '美味減塩・糖質制限レシピ', '冷蔵庫活用作り置き'], false, true, '愛媛県松山市河原町8-5', ST_SetSRID(ST_MakePoint(132.774, 33.834), 4326), 15, 4.94, 37, true, 'acct_ehime_diet04', '{"badge":"献立表進呈","title":"個別最適化「1週間健康献立表」作成プレゼント","description":"栄養相談をご利用の方に、あなた専用の1週間献立カレンダーを作成進呈！","valid_until":"2026-12-31","discount_type":"gift","discount_value":0}'::jsonb, now(), now()),
  ('34975dbd-ebeb-4d98-a4a2-3abf9e54b5a3', 'スポーツ栄養スペシャリスト。部活動に励む学生から市民ランナーまで、持久力アップや疲労回復のための実践的スポーツ栄養指導・補食アドバイスを行います。', ARRAY['ジュニア＆スポーツ栄養指導', '持久力向上補食プラン', '体脂肪コントロール食事法'], false, true, '愛媛県東温市見奈良1125', ST_SetSRID(ST_MakePoint(132.862, 33.793), 4326), 20, 4.91, 29, true, 'acct_ehime_diet05', NULL, now(), now()),
  ('87d426d5-9d92-4095-a942-42aa98f5edcd', '助産師・母乳育児相談員。乳腺炎や母乳の出にくさ、赤ちゃんの吸い付き不良などのおっぱいトラブルに痛みの少ない乳房マッサージで対応。ご自宅へ出張し安心できる授乳を支えます。', ARRAY['桶谷式母乳マッサージ', '乳腺炎トラブルケア', '産後骨盤チェック＆指導'], false, true, '愛媛県松山市平和通3丁目1-4', ST_SetSRID(ST_MakePoint(132.766, 33.848), 4326), 18, 4.98, 55, true, 'acct_ehime_midwife04', '{"badge":"骨盤チェック付","title":"産後骨盤歪みチェック＆引き締め指導無料付帯","description":"母乳マッサージをご予約の方に産後骨盤ケアの無料チェック付き！","valid_until":"2026-11-30","discount_type":"gift","discount_value":0}'::jsonb, now(), now()),
