  ('141a10b1-19b8-48fb-af7b-8e1e8bf62d4b', '国家資格・視能訓練士。パソコンやスマホの長時間使用による眼精疲労、ピントフリーズ、ドライアイに対する専門的眼筋トレーニングと視環境アセスメントをご提供します。', ARRAY['VDT眼精疲労改善', '両眼視機能・ピント調整', 'ブルーライト＆照明環境指導'], true, true, '愛媛県松山市一番町1丁目8-2', ST_SetSRID(ST_MakePoint(132.771, 33.841), 4326), 15, 4.95, 40, true, 'acct_ehime_ort04', '{"badge":"ホットアイマスク付","title":"温熱ハーブアイマスク無料プレゼント","description":"ビジョントレーニング受講で眼元を温める特製アイマスクを進呈！","valid_until":"2026-11-30","discount_type":"gift","discount_value":0}'::jsonb, now(), now()),
  ('1c9b1428-0c88-454e-af9d-5efbb6fc4d27', '今治市・西条市対応。お子様の「本を読むのが遅い」「黒板の文字を写すのが苦手」といった見え方の課題に対し、眼球運動や空間認知を育てるビジョントレーニングを楽しく指導します。', ARRAY['小児ビジョントレーニング', '学習支援・眼球運動訓練', '斜視・弱視相談'], false, true, '愛媛県今治市中浜町1丁目4-12', ST_SetSRID(ST_MakePoint(133.001, 34.067), 4326), 20, 4.9, 25, true, 'acct_ehime_ort05', NULL, now(), now())
