  ('94f97c17-bdb3-4bcb-aaa7-43171585fd14', '158deb3f-5133-4612-ad31-8a3b3bdd28f4', '公認心理師による対話メンタルカウンセリング', '仕事や家庭のストレス、不安、不眠について安心できる環境でじっくりお話を伺います。', 8000, 60, 'counseling', true, now(), now()),
  ('5e125ef3-e78e-47a2-a4cc-0f98012eb3a2', '5ace5689-59d7-4bb2-ac99-7d36db6db574', 'マインドフルネス対話＆キャリアコーチング', '自己理解を深め、頭の中のモヤモヤを整理して前向きな行動へ導くメンタルセッション。', 7000, 50, 'counseling', true, now(), now()),
  ('fcf29b5b-8349-4e69-a59c-13ac14c9c377', 'b075c2ea-fa9d-441c-acb9-324f6c3a9e11', 'ご自宅キッチンでの実践離乳食レクチャー＆相談', '普段お使いの調理器具で、手軽に作れる月齢別離乳食の作り方と食べさせ方をマンツーマン指導。', 7500, 70, 'parenting', true, now(), now()),
  ('dec86794-8afb-435b-ae3d-e73d47b2a96a', '33c046ca-5f69-4355-a35d-0b0612c47523', 'イヤイヤ期・乳幼児の子育て個別相談', '子どもの発達に合わせた声かけや寝かしつけのコツをあたたかくアドバイスします。', 6000, 60, 'parenting', true, now(), now()),
  ('e71ae297-1d1f-4ba4-a034-03252bf606c8', '8cdfe1ca-2f83-46a7-a846-72e92fa9d03a', '【一番人気】極上無水ドライヘッドスパ＆眼精疲労 60分', '水を使わず頭皮の筋膜を深層からほぐし、重だるい頭と目の疲れを劇的にリセットします。', 6800, 60, 'beauty', true, now(), now()),
  ('dc34b71e-8c68-4429-a956-be31a0b501e5', '8a0c54d7-eca6-4960-afdd-b9e9d4e0cb7b', '自律神経調整 快眠ドライヘッドマッサージ 60分', '心地よいリズムで頭部のツボを刺激し、副交感神経を優位にして深い睡眠へと導きます。', 6500, 60, 'beauty', true, now(), now()),
  ('cb56d90e-3e6a-4136-a62d-a923922ddd98', '2141f9b9-1fd5-4f31-aada-ba9caee74074', '高濃度炭酸スプレー快眠ヘッドスパ 60分', 'パチパチ弾ける炭酸泡で血行を瞬時に高め、頭の重さや偏頭痛をすっきり解消します。', 7000, 60, 'beauty', true, now(), now()),
  ('37c996ec-cbe1-4f54-af79-074f0be17cf5', '64f74ef0-2862-41a0-adbc-a494ca7708c4', '首肩集中ほぐし＆リフレッシュヘッドスパ 50分', '首・肩・鎖骨まわりまでしっかりオイルフリーで緩める忙しい方のための集中ケア。', 5800, 50, 'beauty', true, now(), now()),
  ('0f90a684-8bf5-4bda-acdd-4abcf558f592', 'bbfcc1bb-a9dc-447f-a8df-aabeb3e2d74b', '毛穴洗浄エクストラクション＆小顔リフト 70分', '毛穴の黒ずみを徹底除去し、筋膜アプローチで引き締まったフェイスラインを実現します。', 8800, 70, 'esthetic', true, now(), now()),
  ('a74edd1a-709f-4f70-a37d-82699ac67736', '2016596f-ab62-45f7-a84f-c1d1cca0a4d2', '全身深層リンパ痩身＆セルライト燃焼 90分', '強めのオールハンド手技で頑固なコリと老廃物を押し流し、驚きの軽さと引き締めを実感。', 11000, 90, 'esthetic', true, now(), now()),
  ('c3d28a18-f682-4e63-a180-46d29700bdb8', 'c7790673-0c93-463b-ab4d-82a1acd430fd', 'オーガニックハーブピーリング美肌再生ケア 60分', '剥離なしのやさしいハーブでお肌のターンオーバーを促進。ニキビ跡やキメの乱れに。', 9500, 60, 'esthetic', true, now(), now()),
