  ('58e55dfa-65a0-44ff-a496-9c99caa73f33', 'a1b6d9aa-9614-49b9-a391-80c92d9c9506', 'シニア向け転倒予防・訪問筋力アップ運動 50分', '椅子に座ってできる安全な自重トレーニング。ご自宅のリビングで無理なく筋力維持。', 5500, 50, 'personal_training', true, now(), now()),
  ('a696d668-b730-4a4f-aef2-c3c4c4612ea1', '70cd443a-87bc-41f8-adc6-6a48cf4bd3f6', '産後ママ特化 骨盤底筋リセット＆ボディメイク 60分', '産後の骨盤の緩みやくびれの復活を目指す、女性専用の安心パーソナル指導。', 7000, 60, 'personal_training', true, now(), now()),
  ('c93037fc-cee2-4cbe-ae71-a63b55b66c3b', '43d1b102-9bc0-4a3f-a3e5-f1c49bda9028', 'ドイツ式角質除去＆痛くない巻き爪補正 60分', '魚の目・タコを専用マシンでつるつるに。痛みのないプレート巻き爪補正にも対応。', 7500, 60, 'footcare', true, now(), now()),
  ('2c86dbdd-d646-475f-acb3-835161081f2e', 'c1677382-36c6-43af-ad31-e7b1e819943d', '足裏アーチ矯正＆フットリフレクソロジー 50分', '偏平足や外反母趾の疲れをケア。足裏反射区への心地よい刺激で全身の血行を促します。', 5800, 50, 'footcare', true, now(), now()),
  ('b2000cc5-d879-4c52-afb8-e5d379e7b8d5', '6f743b58-476c-4375-a6a3-134c93cc4900', 'シニア訪問フットケア＆爪切り・下肢リフレ 60分', '厚くなった爪や手の届かない足の爪をプロが安全にカット。むくみもスッキリ解消。', 6500, 60, 'footcare', true, now(), now()),
