  ('ae4bdcb1-a682-4e9c-a870-92b21f218b8d', 'bd09dc68-0f88-4fb7-a580-b9542f4a2971', 'ストレス低減マインドフルネス対話セッション 60分', '頭のぐるぐる思考を止め、呼吸と身体感覚に意識を向ける実践的メンタルケア。', 7500, 60, 'counseling', true, now(), now()),
  ('21154dfa-ec53-4d62-abda-73da6fa8b761', '394d2376-b0c6-4032-a94e-7510385ed829', '職場復帰・キャリアメンタルサポート 60分', '休職中・復職直後の不安や職場でのコミュニケーションの悩みを一緒に解決へ導きます。', 8000, 60, 'counseling', true, now(), now()),
  ('834c9520-d575-4eed-a702-be0dfd27997a', '322fbe88-d989-44e7-a30b-027745296b3c', '離乳食ステップアップ訪問調理指導＆相談 75分', 'ご自宅の台所で月齢に合った離乳食の固さ・味付けを一緒に確認。手づかみ食べの悩みも解決。', 6500, 75, 'parenting', true, now(), now()),
  ('2fb43881-b7f7-48b1-ac4f-54d03f43c90e', '0310b1a2-7dab-4022-ae60-b12719d5fd42', '夜泣き・寝かしつけ改善訪問アドバイス 60分', '赤ちゃんの睡眠リズムを分析し、ご家族がしっかり睡眠を取れる寝室環境作りをサポート。', 6000, 60, 'parenting', true, now(), now()),
  ('145963fb-8898-4899-a7f6-66b042a2a5e2', 'eb513594-8546-41de-a475-704b816b96a8', '親子スキンシップ＆ベビーマッサージ個別レッスン 50分', '赤ちゃんの便秘やぐずりを解消するやさしいタッチケア。ママのリフレッシュにも最適。', 5000, 50, 'parenting', true, now(), now()),
  ('9874a454-ea64-4848-ae22-cf2681987b5a', 'e97736bf-a91a-4f01-ae76-61a8647ae61e', '極上オーガニックアロマリンパドレナージュ 90分', '厳選精油の香りに包まれる至福のひととき。全身のリンパをくまなく流し老廃物をデトックス。', 10000, 90, 'aroma', true, now(), now()),
  ('e113a35d-e393-4b1c-a562-8d1ab3667519', 'b55d9acb-6c5e-4665-a87a-680847ca88a8', '深層温活ホットストーン＆アロマトリートメント 80分', '温めた玄武岩とアロマオイルのダブル効果で、慢性冷えや深い疲労を芯から解きほぐします。', 9000, 80, 'aroma', true, now(), now()),
  ('b83a6635-511d-4c66-acbc-d81763d2bbe7', '1978a358-7fc6-4689-ada3-707a3d7d1253', '日常生活行為向上・在宅リハビリテーション 60分', '麻痺手のリハビリや自宅内での動作（着替え・トイレ・入浴）の自立度を高める専門指導。', 7000, 60, 'occupational_therapy', true, now(), now()),
