  ('56e04abe-3c59-417f-a26e-4ad878e17f6a', '7050ce64-ab05-4c11-a921-a0d65ee12acf', '失語症コミュニケーション＆発声トレーニング 60分', '言葉の思い出しやはっきりした発声をサポート。ご自宅でリラックスして続けられます。', 6800, 60, 'speech_therapy', true, now(), now()),
